'use strict';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',members:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-3-5"/>',vehicles:'<path d="M3 7h11v11H3zM14 11h4l3 4v3h-7M6 7V4h5M5 18a2 2 0 1 0 4 0m7 0a2 2 0 1 0 4 0M6 10h5m-5 3h5"/>',courses:'<path d="m3 5 8-2 10 2v15l-10-2-8 2zM11 3v15M6 8l2-.5M14 8l4 1m-4 3 4 1"/>',reports:'<rect x="5" y="4" width="15" height="18" rx="2"/><path d="M9 4V2h7v2M8 10h9M8 14h9M8 18h5"/>',appointments:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v5m10-5v5M3 11h18m-14 4h2m4 0h2"/>',progress:'<path d="M4 20V9m7 11V4m7 16v-8M2 21h20"/>',notifications:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',settings:'<path d="M4 7h16M4 17h16M8 4v6m8 4v6"/><circle cx="8" cy="7" r="2"/><circle cx="16" cy="17" r="2"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>'};
const icon=(k)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.vehicles}</svg>`;
const truck=`<svg viewBox="0 0 360 190" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M28 145h300" stroke="#76949e" stroke-width="1" stroke-dasharray="5 7"/><path d="M55 78h147v66H55z" fill="#335b68" stroke="#8aa7b0"/><path d="M202 93h44l28 29v22h-72V93Z" fill="#587c85" stroke="#a2bdc2"/><path d="M211 101h28l17 18h-45v-18Z" fill="#bfd2cd"/><path d="M64 91h39v38H64zm45 0h39v38h-39zm45 0h39v38h-39z" fill="#244655" stroke="#688e99"/><path d="M69 111h29m16 0h28m17 0h28M67 86h124M212 125h10" stroke="#aec4c6"/><path d="M50 135h225v9H50" fill="#bdcca9"/><rect x="210" y="83" width="19" height="9" rx="2" fill="#efbf67"/><rect x="62" y="69" width="129" height="5" rx="2" fill="#a4b9b7"/><path d="M72 65h114" stroke="#7a9a9f"/><circle cx="90" cy="145" r="17" fill="#142f40" stroke="#8ea9b1" stroke-width="3"/><circle cx="90" cy="145" r="7" stroke="#b7c6c4" stroke-width="2"/><circle cx="245" cy="145" r="17" fill="#142f40" stroke="#8ea9b1" stroke-width="3"/><circle cx="245" cy="145" r="7" stroke="#b7c6c4" stroke-width="2"/><path d="M278 132h7m-237-4h5" stroke="#f3bd59" stroke-width="5"/><path d="M296 61v10m-5-5h10M38 46v8m-4-4h8" stroke="#83b3ab"/><path d="m297 102 12 12-12 12" stroke="#d0b46e" stroke-width="2"/></svg>`;
const EMPTY={members:[],users:[],trainers:[],vehicles:[],courses:[],enrollments:[],lessons:[],attempts:[],appointments:[],notifications:[],files:[],reports:[]};
let state={...EMPTY},user=null,route='dashboard',selectedId='',busy=false,quizAttempt=null,courseDraft=null,vehicleDraft=null,reportDraft=null;
let token=localStorage.getItem('kf_session')||sessionStorage.getItem('kf_session')||'';
const setupMode=()=>!window.KF_API_URL;
const staff=()=>!user||user.role!=='participant';
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Vienna'}).format(new Date());
const date=s=>s?new Intl.DateTimeFormat('de-AT',{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Europe/Vienna'}).format(new Date(s.length===10?s+'T12:00:00Z':s)):'—';
const timeDate=s=>s?new Intl.DateTimeFormat('de-AT',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Vienna'}).format(new Date(s)):'—';
const fmtName=m=>m?m.firstName+' '+m.lastName:'Unbekannt';
const byId=(table,id)=>(state[table[0].toLowerCase()+table.slice(1)]||[]).find(x=>x.id===id);
const activeVehicles=()=>state.vehicles.filter(v=>v.active).sort((a,b)=>a.order-b.order);
const courseFor=id=>state.courses.find(c=>c.vehicleId===id&&c.active);
const enrolFor=(mid,cid)=>state.enrollments.find(e=>e.memberId===mid&&e.courseId===cid);
const tag=(text,kind='')=>`<span class="tag ${kind}">${esc(text)}</span>`;
const btn=(text,action,id='',kind='')=>`<button type="button" class="button ${kind}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;
const navBtn=(text,r,kind='')=>`<button type="button" class="button ${kind}" data-nav="${r}">${text}</button>`;
function toast(msg,error=false){$('#toast').textContent=msg;$('#toast').className=error?'error':'';$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,error?8500:4500);}
function empty(title,description,button='',i='vehicles'){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${button}</div>`;}
function heading(k,title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${esc(k)}</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="flex">${actions}</div></div>`;}
function field(label,name,value='',type='text',extra=''){return `<label>${esc(label)}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
function area(label,name,value='',extra=''){return `<label>${esc(label)}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;}
function check(label,name,yes=true,extra=''){return `<label class="check"><input type="checkbox" name="${name}" ${yes?'checked':''} ${extra}>${esc(label)}</label>`;}
function select(label,name,options,value='',extra=''){return `<label>${esc(label)}<select name="${name}" ${extra}>${options.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></label>`;}
function openModal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();$('#modalBody').innerHTML='';}
async function api(action,data={}){if(setupMode())throw Error('Bitte zuerst das eigene Backend unter Einrichtung verbinden.');const response=await fetch(window.KF_API_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,data,token}),signal:AbortSignal.timeout(65000)});let r;try{r=await response.json();}catch{throw Error('Backend hat keine gültige Antwort geliefert. Worker-Adresse und Bereitstellung prüfen.');}if(!r.ok)throw Error(r.error||'Anfrage fehlgeschlagen.');return r.data;}
async function operation(fn){if(busy)return;busy=true;const buttons=$$('button[type=submit], [data-save], .report-actions button');buttons.forEach(x=>x.disabled=true);try{return await fn();}catch(e){toast(e.message||'Speichern fehlgeschlagen.',true);}finally{busy=false;buttons.forEach(x=>x.disabled=false);}}
async function load(){if(setupMode()){state={...EMPTY};user=null;render();return;}try{state=await api('state');user=state.user;render();}catch(e){if(/anmelden|Sitzung|zugeordnet/i.test(e.message)){user=null;loginPage(e.message);}else throw e;}}
function buildNav(){const pages=staff()?[['dashboard','Übersicht'],['members','Teilnehmer'],['vehicles','Fahrzeuge'],['courses','Ausbildungen'],['reports','Übungen & Berichte'],['appointments','Prüfungstermine'],['progress','Ausbildungsstände'],['notifications','Benachrichtigungen'],['settings',setupMode()?'Einrichtung':'Einstellungen']]:[['dashboard','Meine Übersicht'],['courses','Meine Ausbildungen'],['progress','Mein Fortschritt'],['appointments','Prüfungstermine'],['notifications','Benachrichtigungen'],['profile','Meine Nachweise']];$('#nav').innerHTML=pages.map(([r,label],i)=>`${i===(staff()?7:4)?'<div class="nav-heading">PERSÖNLICH</div>':''}<button data-nav="${r}" class="${route===r?'active':''}">${icon(r==='profile'?'members':r)}<span>${label}</span></button>`).join('');$('#accountName').innerHTML=user?`${esc(user.name)}<small>${user.role==='admin'?'Administrator':user.role==='trainer'?'Ausbilder':'Teilnehmer'}</small>`:'Deine Ausbildungsplattform<small>Einrichtung erforderlich</small>';$('#avatar').textContent=user?user.name.split(' ').map(x=>x[0]).slice(0,2).join(''):'KF';$('#connection').textContent=setupMode()?'Einrichtung offen':'Verbunden · '+(state.version||'');$('#connection').className='connection '+(setupMode()?'':'connected');$('#setupBanner').hidden=!setupMode();$('#notificationDot').hidden=!state.notifications.some(n=>!n.read);$('#breadcrumb').textContent=(pages.find(x=>x[0]===route)||[0,'Übersicht'])[1];}
function navigate(r,id=''){if(busy)return;route=r;selectedId=id;reportDraft=null;window.location.hash=r;$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'});}
function render(){if(!setupMode()&&!user){loginPage();return;}buildNav();const renderers={dashboard:dashboard,members:membersPage,vehicles:vehiclesPage,courses:coursesPage,reports:reportsPage,appointments:appointmentsPage,progress:progressPage,notifications:notificationsPage,settings:settingsPage,profile:profilePage};if(!staff()&&['members','vehicles','reports','settings'].includes(route))route='dashboard';(renderers[route]||dashboard)();}
function dashboard(){const s=state,completed=s.enrollments.filter(e=>e.completedAt).length,lessons=s.lessons.filter(l=>!l.void).length,openRequests=s.appointments.filter(a=>a.status==='requested').length,first=user?user.name.split(' ')[0]:'Willkommen',isStaff=staff();$('#content').innerHTML=`<div class="page-heading"><div><span class="eyebrow">DEIN AUSBILDUNGSCOCKPIT</span><h1>${setupMode()?'Bereit für den nächsten Schritt.':`Servus, ${esc(first)}.`}</h1><p>${isStaff?'Ausbildungen begleiten. Fortschritte im Blick behalten.':'Deine Fahrzeuge, deine nächsten Schritte und deine Erfolge an einem Ort.'}</p></div><span class="tag grey">${new Intl.DateTimeFormat('de-AT',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Vienna'}).format(new Date())}</span></div><section class="hero"><div class="hero-copy"><span class="eyebrow">KRAFTFAHRERAUSBILDUNG · FEUERWEHR ST. PÖLTEN-STADT</span><h1>Fahrzeuge verstehen.<br>Sicherheit erfahren.</h1><p>${isStaff?'Von der ersten Theorie bis zur sicheren Praxis. Begleite dein Team Schritt für Schritt zur abgeschlossenen Fahrzeugausbildung.':'Lerne dein Fahrzeug kennen, sammle praktische Erfahrung und meistere deine nächste Fahrzeugausbildung.'}</p>${navBtn(isStaff?'Ausbildungen verwalten &nbsp; ↗':'Meine Ausbildungen &nbsp; ↗','courses','amber')}<div class="hero-chips"><span>01 &nbsp; THEORIE</span><span>02 &nbsp; EINSCHULUNG</span><span>03 &nbsp; PRÜFUNG</span></div></div><div class="hero-art">${truck}</div></section><div class="stats">${[[isStaff?'Aktive Teilnehmer':'Meine Ausbildungen',isStaff?s.members.filter(m=>m.active).length:s.enrollments.length,'members',isStaff?'Im Ausbildungsprogramm':'Zugeordnete Fahrzeuge'],['Ausbildungsfahrzeuge',s.vehicles.filter(v=>v.active).length,'vehicles','Für Theorie und Praxis'],['Abgeschlossene Ausbildungen',completed,'check','Bestätigt und angerechnet'],[isStaff?'Offene Terminanfragen':'Meine Einschulungen',isStaff?openRequests:lessons,isStaff?'appointments':'reports',isStaff?'Praktische Prüfungen':'Bestätigte Praxistermine']].map(([label,n,i,h])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${setupMode()?'—':n}</div><small>${setupMode()?'Nach der Einrichtung verfügbar':h}</small></div>`).join('')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><h2>Direkt zum nächsten Schritt</h2>${tag('SCHNELLZUGRIFF','grey')}</div><div class="quick-grid">${(isStaff?[['members','Teilnehmer anlegen','Zugänge & Führerscheine','newMember'],['reports','Donnerstagsübung','Anwesenheit & Einschulungen','newThursday'],['reports','Außerordentliche Übung','Ausbildung oder Prüfung','newExtra']]:[['courses','Theorie lernen','Dein Fahrzeug kennenlernen',''],['progress','Fortschritt ansehen','Deine nächsten Schritte',''],['appointments','Prüfung vereinbaren','Mit einem Ausbilder abstimmen','']]).map(([r,t,d,a])=>`<button class="quick" ${a?`data-action="${a}"`:`data-nav="${r}"`}>${icon(r)}<span class="arrow">↗</span><strong>${t}</strong><small>${d}</small></button>`).join('')}</div></section><section class="panel spacer"><div class="panel-head"><h2>${isStaff?'Aktuelle Fahrzeugausbildungen':'Dein nächstes Fahrzeug'}</h2><button class="text-button" data-nav="${isStaff?'progress':'courses'}">Alle ansehen <span>→</span></button></div>${isStaff?dashboardEnrolments():dashboardOwn()}<div class="training-note"><strong>Einmal geschafft. Dauerhaft angerechnet.</strong><p>Bestätigte Quiz und Fahrzeugabschlüsse bleiben bei späteren Inhaltsänderungen erhalten.</p></div></section></div><div><section class="panel"><div class="panel-head"><h2>Der Weg zum Fahrzeug</h2></div><div class="steps">${[['01','Verstehen & vorbereiten','Fahrzeugdaten, Geräteräume und Lerninhalte eigenständig durcharbeiten.'],['02','Wissen & Erfahrung sammeln','Pflichtquiz bestehen und die vorgesehenen Einschulungen absolvieren.'],['03','Sicher in die Praxis','Praktische Prüfung vereinbaren und den Abschluss bestätigen lassen.']].map(([n,t,d])=>`<div class="step"><span class="step-num">${n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></section><section class="panel spacer"><div class="panel-head"><h2>Wichtige Hinweise</h2>${icon('clock')}</div>${expirySummary()}<div class="mini-list"><button data-nav="reports" ${!isStaff?'hidden':''}><span class="grow"><strong>Donnerstag ist Kraftfahrertag.</strong><small>Anwesenheit und Fahrzeugzuordnung gemeinsam erfassen.</small></span><span>↗</span></button><button data-nav="notifications"><span class="grow"><strong>Alle Benachrichtigungen</strong><small>${state.notifications.filter(n=>!n.read).length} ungelesene Meldungen</small></span><span>↗</span></button></div></section></div></div>`;}
function dashboardEnrolments(){if(!state.enrollments.length)return empty('Dein Ausbildungsbetrieb beginnt hier.','Lege Fahrzeuge und Ausbildungen an und nimm anschließend deine Teilnehmer auf.',navBtn('Fahrzeuge anlegen →','vehicles','secondary small'));return `<div class="mini-list">${state.enrollments.filter(e=>!e.completedAt).slice(0,4).map(e=>`<button data-action="enrollment" data-id="${e.id}"><span class="avatar">${esc(byId('Vehicles',e.vehicleId)?.order||'→')}</span><span class="grow"><strong>${esc(fmtName(byId('Members',e.memberId)))}</strong><small>${esc(byId('Vehicles',e.vehicleId)?.name)} · ${e.lessons}/${e.requirements.requiredSessions} Einschulungen</small></span>${tag(e.theoryOk?'Theorie erfüllt':'In Ausbildung',e.theoryOk?'':'amber')}</button>`).join('')||empty('Alle Ausbildungen abgeschlossen.','Neue Ausbildungen kannst du jederzeit gezielt zuordnen.')} </div>`;}
function dashboardOwn(){const es=state.enrollments.filter(e=>!e.completedAt).sort((a,b)=>(byId('Vehicles',a.vehicleId)?.order||0)-(byId('Vehicles',b.vehicleId)?.order||0));return es.length?enrolCard(es[0]):empty('Noch keine Ausbildung zugeordnet.','Dein Ausbilder ordnet dir die vorgesehenen Fahrzeugausbildungen zu.');}
function expiryItems(){const limit=new Date();limit.setDate(limit.getDate()+60);const until=limit.toISOString().slice(0,10);return state.members.filter(m=>m.active).flatMap(m=>(m.licences||[]).filter(l=>l.expires&&l.expires<=until).map(l=>({member:m,label:l.class,expires:l.expires})).concat(m.fireLicenceExpires&&m.fireLicenceExpires<=until?[{member:m,label:'Feuerwehrführerschein',expires:m.fireLicenceExpires}]:[]));}
function expirySummary(){const list=expiryItems();return list.length?`<div class="notice amber">${list.length} Nachweis${list.length===1?'':'e'} ${list.length===1?'läuft':'laufen'} innerhalb von 60 Tagen ab oder ${list.length===1?'ist':'sind'} bereits abgelaufen.</div>`:`<p class="small muted">${setupMode()?'Ablaufdaten und wichtige Ausbildungsereignisse erscheinen nach der Einrichtung hier.':'Keine Führerscheinnachweise innerhalb der nächsten 60 Tage fällig.'}</p>`;}
function membersPage(){if(selectedId){memberDetail(selectedId);return;}$('#content').innerHTML=heading('DEIN TEAM','Teilnehmer','Stammdaten, Führerscheine und Fahrzeugausbildungen an einem Ort.',btn('+ Teilnehmer anlegen','newMember'))+`<div class="panel"><div class="filters"><input id="memberSearch" placeholder="Name oder Standesbuchnummer suchen" aria-label="Teilnehmer suchen"><select id="memberActive" aria-label="Status"><option value="active">Aktive Teilnehmer</option><option value="all">Alle Teilnehmer</option></select></div><div id="memberTable"></div></div>`;renderMemberTable();$('#memberSearch').oninput=renderMemberTable;$('#memberActive').onchange=renderMemberTable;}
function renderMemberTable(){const q=($('#memberSearch')?.value||'').toLowerCase(),all=$('#memberActive')?.value==='all';const members=state.members.filter(m=>(all||m.active)&&`${fmtName(m)} ${m.number}`.toLowerCase().includes(q));$('#memberTable').innerHTML=members.length?`<div class="table-wrap"><table><thead><tr><th>Teilnehmer</th><th>Standesbuchnummer</th><th>Führerscheinklassen</th><th>Ausbildungsstand</th><th></th></tr></thead><tbody>${members.map(m=>{const es=state.enrollments.filter(e=>e.memberId===m.id);return `<tr><td><strong>${esc(fmtName(m))}</strong><small>${esc(m.email)}${!m.active?' · Deaktiviert':''}</small></td><td>${esc(m.number)}</td><td>${(m.licences||[]).map(l=>tag(l.class,l.expires&&l.expires<today()?'red':'grey')).join(' ')||'—'}</td><td>${es.filter(e=>e.completedAt).length} / ${es.length} Fahrzeuge</td><td><button class="table-action" data-action="member" data-id="${m.id}">Verwalten →</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('Noch keine passenden Teilnehmer.','Lege ein Mitglied mit Standesbuchnummer, Führerscheinklassen und eigenem Zugang an.',btn('+ Teilnehmer anlegen','newMember','','secondary small'),'members');}
const CLASSES=['AM','A1','A2','A','B','BE','C1','C1E','C','CE','D1','D1E','D','DE','F'];
function memberForm(id=''){const m=byId('Members',id)||{active:true,startDate:today(),licences:[]};openModal(id?'Teilnehmer bearbeiten':'Teilnehmer anlegen',`<form id="memberForm" data-id="${id}"><div class="form-grid">${field('Vorname *','firstName',m.firstName,'text','required maxlength="80"')}${field('Nachname *','lastName',m.lastName,'text','required maxlength="80"')}${field('Standesbuchnummer *','number',m.number,'text','required maxlength="40"')}${field('E-Mail für den App-Zugang *','email',m.email,'email','required')}${field('Telefon','phone',m.phone,'tel')}${field('Ausbildungsbeginn','startDate',m.startDate,'date','required')}${field('Feuerwehrführerschein gültig bis (falls befristet)','fireLicenceExpires',m.fireLicenceExpires,'date')}${check('Teilnehmer und Zugang aktiv','active',m.active)}</div><div class="form-section"><h3>Führerscheinklassen</h3><p class="help">Vorhandene Klassen anhaken. Ein Ablaufdatum kann je Klasse hinterlegt werden. Die Fahrzeugfreigabe richtet sich nach den ausdrücklich am Fahrzeug eingestellten Klassen.</p><div class="licence-grid">${CLASSES.map(c=>{const l=m.licences.find(l=>l.class===c);return `<div class="licence-cell">${check(c,'class_'+c,!!l)}<label class="help">Gültig bis<input type="date" name="expiry_${c}" value="${esc(l?.expires||'')}" aria-label="${c} gültig bis"></label></div>`;}).join('')}</div></div><div class="notice spacer">Führerscheinkopie und gegebenenfalls Feuerwehrführerschein kannst du nach dem Speichern im Teilnehmerprofil hochladen. Neue Teilnehmer erhalten die aktuell gültigen Ausbildungen. Bestehende Zuordnungen werden beim Bearbeiten nicht verändert.</div><div class="form-actions">${btn('Abbrechen','close','','secondary')}<button class="button" type="submit">Teilnehmer speichern</button></div></form>`);}
function memberDetail(id){const m=byId('Members',id);if(!m){navigate('members');return;}const es=state.enrollments.filter(e=>e.memberId===id);$('#content').innerHTML=heading('TEILNEHMERPROFIL',fmtName(m),`Standesbuchnummer ${m.number} · Ausbildungsbeginn ${date(m.startDate)}`,btn('← Zur Liste','membersBack','','secondary')+btn('Bearbeiten','editMember',id))+`<div class="two-cols"><div><div class="panel"><div class="panel-head"><h2>Fahrzeugausbildungen</h2>${btn('+ Ausbildung zuordnen','assignCourse',id,'secondary small')}</div>${es.map(enrolCard).join('')||empty('Noch keine Fahrzeugausbildung.','Ordne gezielt eine vorhandene Ausbildung zu.')}</div><div class="panel spacer"><h2>Führerscheinklassen</h2><div class="table-wrap"><table><thead><tr><th>Klasse</th><th>Gültig bis</th><th>Status</th></tr></thead><tbody>${m.licences.map(l=>`<tr><td>${tag(l.class)}</td><td>${l.expires?date(l.expires):'Kein Ablauf hinterlegt'}</td><td>${tag(l.expires&&l.expires<today()?'Abgelaufen':'Erfasst',l.expires&&l.expires<today()?'red':'grey')}</td></tr>`).join('')}</tbody></table></div></div></div><div><div class="panel"><h2>Kontakt & Zugang</h2><p class="small">${esc(m.email)}<br>${esc(m.phone||'Keine Telefonnummer hinterlegt')}</p><p>${tag(m.active?'Aktiv':'Deaktiviert',m.active?'':'grey')}</p><div class="inline-actions">${btn('Einladungslink erstellen','invite',m.userId,'secondary small')}${btn('Einladung per Mail senden','emailInvite',m.userId,'small')}</div><p class="help">Eine neue Einladung ersetzt frühere offene Links. Ein vorhandenes Passwort bleibt bis zur Annahme gültig. Der Link dient auch zum Zurücksetzen des Passworts.</p></div><div class="panel spacer"><div class="panel-head"><h2>Führerscheinnachweise</h2>${btn('+ Hochladen','upload',id,'secondary small')}</div>${filesList(id)}<p class="help">Kopien liegen privat in Google Drive. Zugriff erhalten nur Ausbilder, Administration und der betreffende Teilnehmer.</p></div></div></div>`;}
function filesList(mid){const fs=state.files.filter(f=>f.memberId===mid);return fs.length?`<div class="mini-list">${fs.map(f=>`<button data-action="download" data-id="${f.id}"><span class="grow"><strong>${f.kind==='licence'?'Führerschein':'Feuerwehrführerschein'}</strong><small>${esc(f.name)} · ${date(f.at)}</small></span><span>↓</span></button>`).join('')}</div>`:empty('Noch keine Nachweise.','Führerschein als PDF, JPEG oder PNG hinterlegen.','','reports');}
function enrolCard(e){const c=byId('Courses',e.courseId),v=byId('Vehicles',e.vehicleId),req=e.requirements,percent=e.completedAt?100:Math.round(((e.theoryOk?1:0)+Math.min(1,e.lessons/Math.max(1,req.requiredSessions)))/3*100);return `<div class="progress-panel"><div class="panel-head"><div><h3>${esc(v?.name||'Fahrzeug')}</h3><span class="small muted">${esc(c?.title||'Fahrzeugausbildung')}</span></div>${tag(e.completedAt?'Abgeschlossen':e.canExam?'Bereit zur Prüfung':'In Ausbildung',e.completedAt?'':e.canExam?'':'amber')}</div><div class="progress-text"><span>${e.lessons} / ${req.requiredSessions} praktische Einschulungen</span><span>${e.completedAt?date(e.completedAt):percent+' %'}</span></div><div class="progress"><span style="width:${percent}%"></span></div><div class="progress-stage"><span class="stage ${e.theoryOk?'done':''}">${e.theoryOk?'✓':'1'} Theorie ${req.quizRequired?'& Pflichtquiz':''}</span><span class="stage ${e.lessons>=req.requiredSessions?'done':''}">${e.lessons>=req.requiredSessions?'✓':'2'} Einschulungen</span><span class="stage ${e.completedAt?'done':''}">${e.completedAt?'✓':'3'} ${req.practicalEnabled?'Prüfung':'Freigabe'}</span></div><div class="vehicle-foot"><span class="help">${e.recognition?'Vorhandene Ausbildung anerkannt':e.completedAt?'Dauerhaft angerechnet':'Anforderungen bei Zuordnung: Version '+e.courseRevision}</span>${btn(staff()?'Details & Eintragen →':'Ausbildung öffnen →','enrollment',e.id,'secondary small')}</div></div>`;}
function vehiclesPage(){$('#content').innerHTML=heading('FAHRZEUGVERWALTUNG','Unsere Ausbildungsfahrzeuge','Fahrzeuge, Geräteräume, Beladung und technische Daten verwalten.',btn('+ Fahrzeug anlegen','newVehicle'))+(activeVehicles().length?`<div class="cards">${activeVehicles().map(v=>`<article class="vehicle-card"><div class="vehicle-top">${tag('FAHRZEUG '+String(v.order).padStart(2,'0'),'grey')}${truck}</div><div class="vehicle-body"><h3>${esc(v.name)}</h3><p>${esc(v.description||'Technik kennenlernen. Praxis sicher beherrschen.')}</p><div class="vehicle-meta"><span>${v.rooms.length} Geräteräume</span><span>${v.rooms.reduce((n,r)=>n+r.items.length,0)} Geräte</span><span>${esc((v.requiredClasses||[]).join(' / ')||'Klasse individuell')}</span></div><div class="vehicle-foot">${tag(courseFor(v.id)?'Ausbildung angelegt':'Ausbildung offen',courseFor(v.id)?'':'amber')}${btn('Bearbeiten →','editVehicle',v.id,'secondary small')}</div></div></article>`).join('')}</div>`:`<div class="panel">${empty('Hier beginnt deine Fahrzeugausbildung.','Lege das erste Fahrzeug an. Geräteräume und Beladung kannst du anschließend direkt im Fahrzeug bearbeiten.',btn('+ Erstes Fahrzeug anlegen','newVehicle','','secondary'),'vehicles')}</div>`);}
function vehicleForm(id=''){vehicleDraft=structuredClone(byId('Vehicles',id)||{name:'',description:'',technicalData:'',rooms:[],order:state.vehicles.length+1,requiredClasses:[],active:true});renderVehicleForm();}
function renderVehicleForm(){const v=vehicleDraft;openModal(v.id?'Fahrzeug bearbeiten':'Fahrzeug anlegen',`<form id="vehicleForm"><div class="form-grid">${field('Fahrzeugname *','name',v.name,'text','required')}${field('Position in der Ausbildungsreihenfolge','order',v.order,'number','min="1" max="999" required')}<div class="full">${area('Kurzbeschreibung','description',v.description)}</div><div class="full">${area('Technische Daten','technicalData',v.technicalData,'placeholder="Zum Beispiel: Fahrgestell, Gesamtgewicht, Abmessungen, Leistung, Tankinhalt, Besonderheiten …"')}</div><div class="full"><label>Für dieses Fahrzeug akzeptierte Führerscheinklassen</label><div class="check-grid">${CLASSES.map(c=>check(c,'requiredClass_'+c,v.requiredClasses.includes(c))).join('')}</div><p class="help">Mindestens eine der ausgewählten Klassen muss gültig vorhanden sein. Klassen werden ausschließlich nach deiner Konfiguration geprüft; keine automatische rechtliche Bewertung.</p></div>${check('Fahrzeug aktiv','active',v.active)}</div><div class="form-section"><div class="panel-head"><h3>Geräteräume & Beladung</h3>${btn('+ Geräteraum','addRoom','','secondary small')}</div><p class="help">Räume benennen, Geräte eintragen. Die Beladung kann später für Zuordnungsfragen im Quiz übernommen werden.</p>${v.rooms.map((r,ri)=>`<div class="editor-box" data-room="${ri}"><div class="row">${field('Bezeichnung','room_'+ri,r.name,'text','required')}${btn('Entfernen','removeRoom',ri,'danger small')}</div><label>Geräte – ein Gerät je Zeile<textarea name="items_${ri}" placeholder="Schlauchtragekorb\nVerteiler\nStrahlrohr">${esc(r.items.map(i=>i.name).join('\n'))}</textarea></label></div>`).join('')||'<p class="muted small">Noch keine Geräteräume angelegt.</p>'}</div><div class="form-actions">${btn('Abbrechen','close','','secondary')}<button class="button" type="submit">Fahrzeug speichern</button></div></form>`);}
function collectVehicle(){const f=$('#vehicleForm'),d=new FormData(f);Object.assign(vehicleDraft,{name:d.get('name'),order:Number(d.get('order')),description:d.get('description'),technicalData:d.get('technicalData'),active:d.has('active'),requiredClasses:CLASSES.filter(c=>d.has('requiredClass_'+c))});vehicleDraft.rooms=vehicleDraft.rooms.map((r,ri)=>({...r,name:d.get('room_'+ri),items:String(d.get('items_'+ri)||'').split('\n').map(s=>s.trim()).filter(Boolean).map((name,ii)=>{const same=r.items.find(i=>i.name===name);return {id:same?.id||crypto.randomUUID(),name,description:same?.description||''};})}));}
function coursesPage(){if(selectedId){courseRead(selectedId);return;}const list=staff()?state.courses.filter(c=>c.active):state.courses.filter(c=>state.enrollments.some(e=>e.courseId===c.id));$('#content').innerHTML=heading(staff()?'AUSBILDUNGSPLAN':'DEIN LERNBEREICH',staff()?'Fahrzeugausbildungen':'Meine Ausbildungen',staff()?'Theorie, Quiz und praktische Anforderungen je Fahrzeug festlegen.':'Lerne in deinem Tempo. Bestätigte Erfolge bleiben dauerhaft erhalten.',staff()?btn('+ Ausbildung anlegen','newCourse'):'')+(list.length?`<div class="cards">${list.sort((a,b)=>(byId('Vehicles',a.vehicleId)?.order||0)-(byId('Vehicles',b.vehicleId)?.order||0)).map(c=>`<article class="vehicle-card"><div class="vehicle-top">${tag('VERSION '+c.revision,'grey')}${truck}</div><div class="vehicle-body"><span class="eyebrow">${esc(byId('Vehicles',c.vehicleId)?.name)}</span><h3>${esc(c.title)}</h3><p>${esc(c.objectives.slice(0,140)||'Ausbildungsinhalte und Lernziele kennenlernen.')}</p><div class="vehicle-meta"><span>${c.theoryEnabled?'Mit Theorie':'Praxisorientiert'}</span><span>${c.requiredSessions} Einschulungen</span>${c.quiz.enabled?`<span>${c.quiz.required?'Pflichtquiz':'Freiwilliges Quiz'}</span>`:''}</div><div class="vehicle-foot">${staff()?btn('Bearbeiten','editCourse',c.id,'secondary small'):''}${btn(staff()?'Inhalte ansehen →':'Lernen & Fortschritt →','readCourse',c.id,'small')}</div></div></article>`).join('')}</div>`:`<div class="panel">${empty(staff()?'Noch keine Ausbildung angelegt.':'Noch keine Ausbildung zugeordnet.',staff()?'Lege zunächst ein Fahrzeug und anschließend die zugehörige Ausbildung an.':'Dein Ausbilder stellt dir deine Fahrzeugausbildungen hier bereit.',staff()?btn('+ Ausbildung anlegen','newCourse','','secondary'):'','courses')}</div>`);}
function courseForm(id=''){if(!state.vehicles.length){toast('Bitte zuerst ein Fahrzeug anlegen.',true);return;}courseDraft=structuredClone(byId('Courses',id)||{vehicleId:activeVehicles()[0]?.id||state.vehicles[0].id,title:'',content:'',objectives:'',presentation:'',materials:[],workMaterials:'',responsibleTrainerIds:[],sections:[],requiredSessions:7,theoryEnabled:true,practicalEnabled:true,effectiveFrom:today(),prerequisiteVehicleIds:[],active:true,quiz:{enabled:false,required:true,passPercent:80,maxAttempts:3,questions:[]}});renderCourseForm();}
function renderCourseForm(){const c=courseDraft;openModal(c.id?'Ausbildung bearbeiten':'Ausbildung anlegen',`<form id="courseForm">${c.id?'<div class="notice">Du bearbeitest die nächste Inhaltsversion. Bereits bestandene Quiz, Abschlüsse und zugeordnete Anforderungen bleiben angerechnet. Bestehende Fragen werden vollständig geladen.</div>':''}<div class="form-grid">${field('Ausbildungsbezeichnung *','title',c.title,'text','required')}${select('Fahrzeug *','vehicleId',state.vehicles.map(v=>[v.id,v.name]),c.vehicleId,c.id?'disabled':'required')}${field('Erforderliche praktische Einschulungen','requiredSessions',c.requiredSessions,'number','min="0" max="50" required')}${field('Gültig für neue Ausbildungsbeginne ab','effectiveFrom',c.effectiveFrom,'date')}${check('Theoretische Ausbildung vorgesehen','theoryEnabled',c.theoryEnabled)}${check('Praktische Abschlussprüfung vorgesehen','practicalEnabled',c.practicalEnabled)}<div class="full">${area('Ausbildungsinhalt / Kursbeschreibung','content',c.content)}</div><div class="full">${area('Ausbildungsziele','objectives',c.objectives)}</div></div><div class="form-section"><h3>Reihenfolge & Voraussetzungen</h3><div class="check-grid">${activeVehicles().filter(v=>v.id!==c.vehicleId).map(v=>check(v.name,'pre_'+v.id,c.prerequisiteVehicleIds.includes(v.id))).join('')||'<p class="help">Weitere Fahrzeuge anlegen, um Voraussetzungen festzulegen.</p>'}</div><p class="help">Ausgewählte Fahrzeuge müssen zuvor abgeschlossen sein. Die Reihenfolge der Übersicht wird zusätzlich über die Fahrzeugposition festgelegt.</p></div><div class="form-section"><h3>Lernabschnitte für Teilnehmer</h3><p class="help">Technische Daten und Geräteräume stehen automatisch im Lernbereich. Hier kannst du weitere Seiten hinzufügen.</p>${c.sections.map((s,i)=>`<div class="editor-box">${field('Überschrift','sectionTitle_'+i,s.title)}${area('Lerninhalt','sectionBody_'+i,s.body)}<div class="spacer">${btn('Abschnitt entfernen','removeSection',i,'danger small')}</div></div>`).join('')}${btn('+ Lernabschnitt','addSection','','secondary small')}</div><div class="form-section"><h3>Ausbilderunterlagen & Vorbereitung</h3><p class="help">Diese Felder sehen nur Ausbilder und Administration. Die Teilnehmer sehen die Lernabschnitte, Kursbeschreibung, Lernziele und Fahrzeugdaten.</p>${field('Präsentationslink','presentation',c.presentation,'url')}${area('Arbeitsmaterial / Vorbereitung','workMaterials',c.workMaterials)}<label>Dokumentenlinks – je Zeile: Bezeichnung | https://…<textarea name="materials">${esc(c.materials.map(x=>x.name+' | '+x.url).join('\n'))}</textarea></label><label class="spacer">Verantwortliche Ausbilder (Übersicht)</label><div class="check-grid">${state.trainers.map(t=>check(t.name,'responsible_'+t.id,c.responsibleTrainerIds.includes(t.id))).join('')}</div><p class="help">Die Zuordnung ist organisatorisch. Jeder aktive Ausbilder kann eine Ausbildung durchführen.</p></div><div class="form-section"><h3>Theoriequiz</h3><div class="check-grid">${check('Quiz aktiv','quizEnabled',c.quiz.enabled)}${check('Pflichtquiz vor praktischer Prüfung','quizRequired',c.quiz.required)}</div><div class="form-grid spacer">${field('Bestehensgrenze in %','passPercent',c.quiz.passPercent,'number','min="1" max="100"')}${field('Maximale Versuche','maxAttempts',c.quiz.maxAttempts,'number','min="1" max="20"')}</div><div id="questionEditors">${c.quiz.questions.map(questionEditor).join('')}</div><div class="inline-actions spacer">${btn('+ Auswahlfrage','addQuestion','choice','secondary small')}${btn('+ Richtig / Falsch','addQuestion','boolean','secondary small')}${btn('+ Ja / Nein','addQuestion','yesno','secondary small')}${btn('+ Geräteraum-Zuordnung','addQuestion','allocation','secondary small')}</div><p class="help">Geräteraumfragen übernehmen die aktuelle Fahrzeugbeladung. Teilnehmer können die Geräte ziehen oder über Auswahlfelder zuordnen – auch am Handy.</p></div><div class="form-section">${check('Ausbildung aktiv','active',c.active)}</div><div class="form-actions">${btn('Abbrechen','close','','secondary')}<button class="button" type="submit">${c.id?'Neue Inhaltsversion speichern':'Ausbildung speichern'}</button></div></form>`);}
function questionEditor(q,i){return `<div class="editor-box" data-question="${i}"><div class="panel-head"><strong class="small">Frage ${i+1} · ${q.type==='allocation'?'Geräteraum-Zuordnung':q.type==='boolean'?'Zwei Antworten':'Auswahlfrage'}</strong>${btn('Entfernen','removeQuestion',i,'danger small')}</div>${area('Fragetext','qtext_'+i,q.text)}${q.type==='allocation'?`<p class="help">Geräte und korrekte Zuordnung aus dem Fahrzeug. Änderungen an Fahrzeugdaten überschreiben diese Quizfrage nicht automatisch.</p>${q.items.map((it,j)=>select(it.name,'qroom_'+i+'_'+j,q.rooms.map(r=>[r.id,r.name]),it.correctRoomId)).join('')}`:`<label>Antwortmöglichkeiten – eine pro Zeile<textarea name="qoptions_${i}" rows="3">${esc(q.options.join('\n'))}</textarea></label>${field('Richtige Antwort (Nummer, beginnend mit 1)','qcorrect_'+i,q.correct+1,'number','min="1" max="8"')}`}</div>`;}
function collectCourse(){const d=new FormData($('#courseForm')),c=courseDraft;c.title=d.get('title');c.vehicleId=d.get('vehicleId')||c.vehicleId;c.requiredSessions=Number(d.get('requiredSessions'));c.effectiveFrom=d.get('effectiveFrom');c.theoryEnabled=d.has('theoryEnabled');c.practicalEnabled=d.has('practicalEnabled');c.content=d.get('content');c.objectives=d.get('objectives');c.presentation=d.get('presentation');c.workMaterials=d.get('workMaterials');c.materials=String(d.get('materials')||'').split('\n').filter(x=>x.trim()).map(line=>{const p=line.indexOf('|');return p<0?{name:'Dokument',url:line.trim()}:{name:line.slice(0,p).trim(),url:line.slice(p+1).trim()};});c.responsibleTrainerIds=state.trainers.filter(t=>d.has('responsible_'+t.id)).map(t=>t.id);c.prerequisiteVehicleIds=state.vehicles.filter(v=>d.has('pre_'+v.id)).map(v=>v.id);c.sections=c.sections.map((s,i)=>({title:d.get('sectionTitle_'+i),body:d.get('sectionBody_'+i)}));c.active=d.has('active');c.quiz={...c.quiz,enabled:d.has('quizEnabled'),required:d.has('quizRequired'),passPercent:Number(d.get('passPercent')),maxAttempts:Number(d.get('maxAttempts')),questions:c.quiz.questions.map((q,i)=>q.type==='allocation'?{...q,text:d.get('qtext_'+i),items:q.items.map((it,j)=>({...it,correctRoomId:d.get('qroom_'+i+'_'+j)}))}:{...q,text:d.get('qtext_'+i),options:String(d.get('qoptions_'+i)||'').split('\n').map(x=>x.trim()),correct:Number(d.get('qcorrect_'+i))-1})};}
function courseRead(id){const c=byId('Courses',id);if(!c){navigate('courses');return;}const v=byId('Vehicles',c.vehicleId),e=state.enrollments.find(e=>e.courseId===id);$('#content').innerHTML=heading(esc(v?.name||'FAHRZEUG'),c.title,c.objectives,btn('← Ausbildungen','coursesBack','','secondary')+(staff()?btn('Inhalte bearbeiten','editCourse',id):''))+`<div class="two-cols"><article class="panel reading"><span class="eyebrow">FAHRZEUG KENNENLERNEN</span><h2>Ausbildungsinhalt</h2><p class="prose">${esc(c.content||'Noch keine Beschreibung hinterlegt.')}</p><h2>Lernziele</h2><p class="prose">${esc(c.objectives||'Noch keine Lernziele hinterlegt.')}</p>${v?.technicalData?`<h2>Technische Daten</h2><div class="prose">${esc(v.technicalData)}</div>`:''}<h2>Geräteräume & Beladung</h2>${(v?.rooms||[]).map(r=>`<details class="room"><summary>${esc(r.name)} <span>${r.items.length} Geräte</span></summary><ul>${r.items.map(i=>`<li><strong>${esc(i.name)}</strong>${i.description?' · '+esc(i.description):''}</li>`).join('')}</ul></details>`).join('')||'<p class="muted small">Noch keine Geräteräume hinterlegt.</p>'}${(c.sections||[]).map(s=>`<h2>${esc(s.title)}</h2><p class="prose">${esc(s.body)}</p>`).join('')}${staff()?`<div class="form-section"><h2>Ausbilderunterlagen</h2>${c.presentation?`<p><a class="button secondary" href="${esc(c.presentation)}" target="_blank" rel="noopener noreferrer">Präsentation öffnen ↗</a></p>`:''}${c.materials.map(x=>`<p><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.name||'Dokument')} ↗</a></p>`).join('')}<h3>Arbeitsmaterial</h3><p class="prose">${esc(c.workMaterials||'Keine zusätzlichen Arbeitsmittel hinterlegt.')}</p><h3>Organisatorisch verantwortlich</h3><p class="small muted">${esc(c.responsibleTrainerIds.map(id=>state.trainers.find(t=>t.id===id)?.name||'').join(', ')||'Noch nicht zugeordnet. Jeder aktive Ausbilder kann ausbilden.')}</p></div>`:''}</article><aside><div class="panel"><h2>Dein Ausbildungsweg</h2>${e?enrolCard(e):`<p class="small muted">${staff()?'Die Anforderungen werden bei der Teilnehmerzuordnung festgehalten.':'Bitte Ausbilder um Zuordnung bitten.'}</p>`}${!staff()&&e&&!e.completedAt?`<hr>${e.theoryLearned?'<div class="notice">✓ Lerninhalte als durchgearbeitet bestätigt.</div>':btn('Lerninhalte durchgearbeitet ✓','learning',e.id,'teal')}${(c.quiz.enabled||e.requirements.quizRequired)?`<div class="spacer">${e.quizPassed&&e.requirements.quizRequired?'<div class="notice">✓ Pflichtquiz bereits bestanden. Du musst es nach einer Inhaltsänderung nicht wiederholen.</div>':btn(e.requirements.quizRequired?'Pflichtquiz starten →':'Freiwilliges Quiz starten →','startQuiz',e.id,'teal')}</div>`:''}${e.canExam&&e.requirements.practicalEnabled?`<div class="spacer">${btn('Prüfungstermin anfragen','book',e.id,'secondary')}</div>`:''}`:''}<p class="help spacer">${c.requiredSessions} Einschulungen laut aktueller Kursversion. Bei bereits zugeordneten Ausbildungen gelten die im Fortschritt angeführten Anforderungen.</p></div></aside></div>`;}
function progressPage(){const list=state.enrollments;$('#content').innerHTML=heading('AUSBILDUNGSPASS',staff()?'Ausbildungsstände':'Mein Fortschritt','Bestätigte Einschulungen, bestandene Quiz und anerkannte Fahrzeugabschlüsse.')+`<div class="stats" style="margin-bottom:24px">${[['Ausbildungen',list.length],['Abgeschlossen',list.filter(e=>e.completedAt).length],['Theorie erfüllt',list.filter(e=>e.theoryOk).length],['Bestätigte Einschulungen',state.lessons.filter(l=>!l.void).length]].map(([t,n])=>`<div class="stat"><div class="stat-top">${t}</div><div class="stat-value">${setupMode()?'—':n}</div></div>`).join('')}</div>${staff()?'<div class="filters"><input id="progressSearch" placeholder="Teilnehmer oder Fahrzeug suchen" aria-label="Ausbildungsstände suchen"></div>':''}<div id="progressList">${progressList(list)}</div>`;if($('#progressSearch'))$('#progressSearch').oninput=()=>{const q=$('#progressSearch').value.toLowerCase();$('#progressList').innerHTML=progressList(list.filter(e=>(fmtName(byId('Members',e.memberId))+' '+byId('Vehicles',e.vehicleId)?.name).toLowerCase().includes(q)));};}
function progressList(es){return es.length?es.map(e=>`${staff()?`<p class="small muted spacer">${esc(fmtName(byId('Members',e.memberId)))} · Stb. ${esc(byId('Members',e.memberId)?.number)}</p>`:''}${enrolCard(e)}`).join(''):`<div class="panel">${empty('Noch keine Ausbildungsstände.','Zugeordnete Fahrzeugausbildungen und bestätigte Einschulungen erscheinen hier.','','progress')}</div>`;}
function enrollmentDetail(id){const e=byId('Enrollments',id);if(!e)return;const c=byId('Courses',e.courseId),v=byId('Vehicles',e.vehicleId),m=byId('Members',e.memberId),lessons=state.lessons.filter(l=>l.enrollmentId===id);openModal(v?.name||'Fahrzeugausbildung',`<p class="small muted">${esc(fmtName(m))} · Stb. ${esc(m?.number)} · ${esc(c?.title)}</p>${enrolCard({...e,id:'modal-'+e.id}).replace(/<div class="vehicle-foot">[\s\S]*?<\/div>/,'')}<div class="inline-actions">${staff()&&!e.completedAt?btn('+ Einschulung eintragen','lesson',id,'teal')+btn('Vorhandene Ausbildung anerkennen','recognize',id,'secondary')+btn(e.requirements.practicalEnabled?'Prüfung bestanden / abschließen':'Ausbildung abschließen','finishCourse',id,'secondary')+btn('Zusatzversuch freigeben','extraAttempt',id,'secondary small'):''}${!staff()?btn('Lernbereich öffnen','openLearning',c?.id,'teal'):''}${e.canExam&&!e.completedAt&&e.requirements.practicalEnabled?btn('Prüfungstermin vereinbaren','book',id,'secondary'):''}</div><div class="form-section"><h3>Bestätigte Einschulungen · ${e.lessons}/${e.requirements.requiredSessions}</h3>${lessons.length?`<div class="mini-list">${lessons.map(l=>`<div class="mini-row"><span class="grow"><strong class="small">${date(l.date)} · ${l.minutes} Minuten ${l.void?'· Storniert':''}</strong><small>${esc(l.trainerName)}${l.location?' · '+esc(l.location):''}</small><p class="help">${esc(l.content||'Fahrzeugeinschulung')}${l.reportId?' · Aus Tätigkeitsbericht':''}</p></span>${staff()&&!e.completedAt&&!l.void?btn('Korrigieren','voidLesson',l.id,'danger small'):''}</div>`).join('')}</div>`:'<p class="small muted">Noch keine praktischen Einschulungen bestätigt.</p>'}</div>${e.quizPassed?`<div class="notice spacer">Quiz bestanden am ${date(e.quizPassed.at)} · ${e.quizPassed.percent} % · Inhaltsversion ${e.quizPassed.revision}. Bleibt nach Änderungen angerechnet.</div>`:''}${e.recognition?`<div class="notice">Vorhandene Ausbildung anerkannt: ${esc(e.recognition.reason)}</div>`:''}`);}
function lessonForm(id){const e=byId('Enrollments',id);openModal('Praktische Einschulung eintragen',`<form id="lessonForm" data-id="${id}" data-key="${crypto.randomUUID()}"><p class="small muted">${esc(fmtName(byId('Members',e.memberId)))} · ${esc(byId('Vehicles',e.vehicleId)?.name)}</p><div class="form-grid">${field('Datum *','date',today(),'date',`required max="${today()}"`)}${field('Dauer in Minuten *','minutes',60,'number','min="1" max="1440" required')}<div class="full">${area('Ausbildungsinhalt / Bemerkung','content','')}</div></div><div class="notice spacer">Diese Bestätigung zählt als eine Einschulung. Für gemeinsame Übungen verwende die Anwesenheitsliste unter „Übungen & Berichte“.</div><div class="form-actions">${btn('Abbrechen','close','','secondary')}<button class="button" type="submit">Einschulung bestätigen</button></div></form>`);}
function finishForm(id,recognition=false){const e=byId('Enrollments',id);openModal(recognition?'Vorhandene Fahrzeugausbildung anerkennen':'Fahrzeugausbildung abschließen',`<form id="finishForm" data-id="${id}" data-recognition="${recognition}"><p class="small muted">${esc(fmtName(byId('Members',e.memberId)))} · ${esc(byId('Vehicles',e.vehicleId)?.name)}</p>${!recognition&&!e.canExam?'<div class="notice amber">Theorie oder erforderliche Einschulungen fehlen noch. Eine reguläre Abschlussbestätigung ist erst nach Erfüllung möglich.</div>':''}${field('Abschlussdatum *','date',today(),'date',`required max="${today()}"`)}${recognition?`${area('Begründung / vorhandener Ausbildungsnachweis *','reason','','required')}<p class="help">Damit bestätigst du eine bereits absolvierte Fahrzeugausbildung. Die Anerkennung wird mit deinem Konto protokolliert.</p>`:e.requirements.practicalEnabled?`<div class="spacer">${check('Praktische Prüfung wurde positiv absolviert','examPassed',false,'required')}</div>`:''}<div class="form-actions">${btn('Abbrechen','close','','secondary')}<button class="button teal" type="submit">${recognition?'Ausbildung anerkennen':'Abschluss bestätigen'}</button></div></form>`);}
function quizRender(a){quizAttempt=a;openModal('Theoriequiz',`<form id="quizForm"><div class="notice">Bestehensgrenze: ${a.passPercent} %. Beantworte alle Fragen. Bei Zuordnungsfragen kannst du Geräte ziehen oder die Auswahlfelder verwenden.</div>${a.questions.map((q,i)=>`<fieldset class="question"><legend>Frage ${i+1} von ${a.questions.length}</legend><h3>${esc(q.text)}</h3>${q.type==='allocation'?`<div class="item-bank" data-qbank="${q.id}">${q.items.map(it=>`<span draggable="true" class="drag-item" data-item="${it.id}" data-q="${q.id}">${esc(it.name)}</span>`).join('')}</div><div class="allocation">${q.rooms.map(r=>`<div class="drop-room" data-roomid="${r.id}" data-q="${q.id}"><h4>${esc(r.name)}</h4><div class="room-items"></div></div>`).join('')}</div><details class="spacer" open><summary class="small muted">Zuordnung per Auswahl / am Handy</summary><div class="assignment-select">${q.items.map(it=>select(it.name,'allocation_'+q.id+'_'+it.id,[['','Geräteraum auswählen'],...q.rooms.map(r=>[r.id,r.name])],'',`required data-allocation-q="${q.id}" data-allocation-item="${it.id}"`)).join('')}</div></details>`:q.options.map((o,j)=>`<label class="answer"><input type="radio" name="answer_${q.id}" value="${j}" required>${esc(o)}</label>`).join('')}</fieldset>`).join('')}<div class="form-actions">${btn('Später fortsetzen','close','','secondary')}<button type="submit" class="button teal">Quiz verbindlich abgeben</button></div></form>`);bindDrag();}
function bindDrag(){let drag=null;$$('.drag-item').forEach(el=>{el.ondragstart=e=>{drag={q:el.dataset.q,item:el.dataset.item};e.dataTransfer.setData('text/plain',JSON.stringify(drag));};});$$('.drop-room').forEach(el=>{el.ondragover=e=>{if(drag?.q===el.dataset.q){e.preventDefault();el.classList.add('over');}};el.ondragleave=()=>el.classList.remove('over');el.ondrop=e=>{e.preventDefault();el.classList.remove('over');if(drag?.q!==el.dataset.q)return;const input=$(`select[data-allocation-q="${CSS.escape(drag.q)}"][data-allocation-item="${CSS.escape(drag.item)}"]`);input.value=el.dataset.roomid;input.dispatchEvent(new Event('change',{bubbles:true}));};});$$('[data-allocation-q]').forEach(s=>s.onchange=()=>{const item=$(`.drag-item[data-q="${CSS.escape(s.dataset.allocationQ)}"][data-item="${CSS.escape(s.dataset.allocationItem)}"]`),target=s.value?$(`.drop-room[data-q="${CSS.escape(s.dataset.allocationQ)}"][data-roomid="${CSS.escape(s.value)}"] .room-items`):$(`[data-qbank="${CSS.escape(s.dataset.allocationQ)}"]`);target?.append(item);});}
function appointmentsPage(){$('#content').innerHTML=heading('PRAXIS PLANEN','Prüfungstermine','Teilnehmer schlagen einen Termin vor. Ein Ausbilder bestätigt die gemeinsame Vereinbarung.',!staff()?btn('+ Termin anfragen','chooseBooking'):'')+`<div class="panel">${state.appointments.length?`<div class="table-wrap"><table><thead><tr><th>Termin</th>${staff()?'<th>Teilnehmer</th>':''}<th>Fahrzeug</th><th>Ausbilder</th><th>Status</th><th></th></tr></thead><tbody>${state.appointments.slice().sort((a,b)=>a.begins.localeCompare(b.begins)).map(a=>{const e=byId('Enrollments',a.enrollmentId);return `<tr><td><strong>${timeDate(a.begins)}</strong><small>${esc(a.note)}</small></td>${staff()?`<td>${esc(fmtName(byId('Members',a.memberId)))}</td>`:''}<td>${esc(byId('Vehicles',e?.vehicleId)?.name)}</td><td>${esc(state.trainers.find(t=>t.id===a.trainerId)?.name)}</td><td>${tag({requested:'Angefragt',confirmed:'Bestätigt',declined:'Abgelehnt',cancelled:'Abgesagt'}[a.status]||a.status,a.status==='requested'?'amber':a.status==='confirmed'?'':'grey')}</td><td>${staff()&&a.status==='requested'?btn('Bestätigen','confirmAppointment',a.id,'small')+btn('Ablehnen','declineAppointment',a.id,'secondary small'):''}${staff()&&a.status==='confirmed'?btn('Absagen','cancelAppointment',a.id,'secondary small'):''}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Noch keine Prüfungstermine.','Nach erfüllter Theorie und den erforderlichen Einschulungen kann der praktische Prüfungstermin angefragt werden.','','appointments')}</div>`;}
function bookingForm(id){const e=byId('Enrollments',id);openModal('Praktischen Prüfungstermin vereinbaren',`<form id="bookingForm" data-id="${id}"><p class="small muted">${esc(byId('Vehicles',e?.vehicleId)?.name)} · ${esc(fmtName(byId('Members',e?.memberId)))}</p><div class="form-grid">${select('Ausbilder *','trainerId',state.trainers.map(t=>[t.id,t.name]),'','required')}${field('Terminvorschlag *','begins','','datetime-local','required')}<div class="full">${area('Ort / Nachricht an den Ausbilder','note','')}</div></div><p class="help">${staff()?'Als Ausbilder angelegte Termine werden bestätigt gespeichert.':'Dein Vorschlag wird erst durch die Bestätigung des Ausbilders verbindlich.'}</p><div class="form-actions">${btn('Abbrechen','close','','secondary')}<button class="button" type="submit">${staff()?'Termin festlegen':'Terminvorschlag senden'}</button></div></form>`);}
function notificationsPage(){$('#content').innerHTML=heading('BLEIB AUF DEM LAUFENDEN','Benachrichtigungen','Quiz-Ergebnisse, Ausbildungsabschlüsse, Terminanfragen und Ablauf-Erinnerungen.',state.notifications.length?btn('Alle als gelesen markieren','readNotifications','','secondary'):'')+`<div class="panel" style="padding:0">${state.notifications.length?state.notifications.map(n=>`<article class="notification ${n.read?'':'unread'}"><div class="panel-head"><h3>${esc(n.title)}</h3>${!n.read?tag('NEU'):''}</div><p>${esc(n.text)}</p><small>${timeDate(n.at)}</small></article>`).join(''):empty('Noch keine Benachrichtigungen.','Wichtige Ereignisse werden hier dauerhaft in deiner App gesammelt.','','notifications')}</div>`;}
function profilePage(){const m=state.members[0];$('#content').innerHTML=heading('PERSÖNLICH','Meine Nachweise','Deine hinterlegten Führerscheinklassen und Dokumente.')+`<div class="two-cols"><section class="panel"><h2>${esc(fmtName(m))}</h2><p class="small muted">Standesbuchnummer ${esc(m?.number)} · ${esc(m?.email)}</p><div class="check-grid">${(m?.licences||[]).map(l=>tag(l.class+(l.expires?' · '+date(l.expires):''),l.expires&&l.expires<today()?'red':'')).join('')}</div>${m?.fireLicenceExpires?`<p class="small spacer">Feuerwehrführerschein gültig bis ${date(m.fireLicenceExpires)}</p>`:''}<p class="help spacer">Für Änderungen an deinen Daten oder Nachweisen wende dich an einen Ausbilder.</p></section><section class="panel"><h2>Führerscheinkopien</h2>${filesList(m?.id)}</section></div>`;}
function reportsPage(){if(reportDraft){renderReportEditor();return;}$('#content').innerHTML=heading('AUSBILDUNG DOKUMENTIEREN','Übungen & Tätigkeitsberichte','Anwesende Teilnehmer abhaken, Fahrzeuge und Ausbilder zuordnen und Einschulungen gemeinsam bestätigen.',btn('+ Donnerstagsübung','newThursday')+btn('+ Außerordentliche Übung / Prüfung','newExtra','','secondary'))+`<div class="notice">Jeder abgeschlossene Übungstermin zählt je Teilnehmer und Fahrzeug höchstens einmal als Einschulung. Mehrere Donnerstage sammeln sich auf, z. B. WLF 3: 1/7 → 2/7 → 7/7. Eine zusätzliche Abschlussprüfung wird separat bestätigt.</div><div class="panel">${state.reports.length?`<div class="table-wrap"><table><thead><tr><th>Übung</th><th>Datum / Ort</th><th>Teilnehmer</th><th>Status</th><th></th></tr></thead><tbody>${state.reports.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td><strong>${esc(r.title)}</strong><small>${reportType(r.type)}</small></td><td>${date(r.date)}<small>${esc(r.location)}</small></td><td>${r.attendees.filter(a=>a.present).length} anwesend</td><td>${tag(r.status==='finished'?'Abgeschlossen':r.status==='finalizing'?'Abschluss fortsetzen':'Entwurf',r.status==='finished'?'':'amber')}${r.emailSentAt?' '+tag('Mail versendet','grey'):''}</td><td>${r.status==='draft'?btn('Bearbeiten →','editReport',r.id,'secondary small'):r.status==='finalizing'?btn('Abschluss fortsetzen','resumeReport',r.id,'secondary small'):btn('Bericht ansehen →','viewReport',r.id,'secondary small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Der nächste Donnerstag kann kommen.','Eine Anwesenheitsliste für alle Teilnehmer. Je Person Fahrzeug, Ausbildungsinhalt, Ausbilder und Gruppe erfassen.',btn('+ Donnerstagsübung erfassen','newThursday','','secondary'),'reports')}</div>`;}
function reportType(t){return {thursday:'Donnerstagsübung',extra:'Außerordentliche Kraftfahrübung',exam:'Außerordentliche Kraftfahrprüfung'}[t]||'Kraftfahrerübung';}
function newReport(type,id=''){const old=byId('Reports',id);reportDraft=old?structuredClone(old):{title:type==='thursday'?'Kraftfahrerübung':type==='exam'?'Außerordentliche Kraftfahrprüfung':'Außerordentliche Kraftfahrübung',type,date:today(),begins:'19:00',ends:'21:00',location:'',note:'',vehicleUse:[],instructorMinutes:{},attendees:state.members.filter(m=>m.active).map(m=>({memberId:m.id,name:fmtName(m),number:m.number,present:false,assignments:[]}))};route='reports';selectedId='';buildNav();renderReportEditor();window.scrollTo({top:0,behavior:'instant'});}
function defaultAssignment(memberId){const e=state.enrollments.find(e=>e.memberId===memberId&&!e.completedAt);return {id:crypto.randomUUID(),vehicleId:e?.vehicleId||'',enrollmentId:e?.id||'',trainerIds:user?[user.id]:[],withMemberIds:[],minutes:60,location:'',content:'',credit:!!e&&reportDraft.type!=='exam'};}
function reportDuration(){const r=reportDraft;if(!r)return 120;const mins=t=>{const p=t.split(':').map(Number);return p[0]*60+p[1];};return Math.max(1,mins(r.ends)-mins(r.begins));}
function renderReportEditor(){const r=reportDraft;$('#content').innerHTML=heading('ANWESENHEIT & AUSBILDUNGSZUORDNUNG',r.id?'Übungsbericht bearbeiten':'Übung erfassen','Du entscheidest je Person, auf welchem Fahrzeug, wo und mit wem ausgebildet wurde.',btn('← Berichte','reportsBack','','secondary'))+`<form id="reportForm"><section class="panel"><div class="form-grid">${field('Bezeichnung *','title',r.title,'text','required')}${select('Art der Ausbildung','type',[['thursday','Donnerstagsübung'],['extra','Außerordentliche Kraftfahrübung'],['exam','Außerordentliche Kraftfahrprüfung']],r.type)}${field('Datum *','date',r.date,'date',`required max="${today()}"`)}${field('Allgemeiner Ausbildungsort *','location',r.location,'text','required')}${field('Beginn *','begins',r.begins,'time','required')}${field('Ende *','ends',r.ends,'time','required')}</div></section><div class="report-toolbar"><div class="flex"><h2 class="no-margin" style="font-size:19px">Anwesenheit & Zuordnung</h2>${tag(r.attendees.filter(a=>a.present).length+' ANWESEND')}</div><div class="flex"><input id="reportSearch" placeholder="Teilnehmer suchen …" aria-label="Anwesenheitsliste durchsuchen" style="max-width:220px">${btn('Alle anhaken','checkAll','','secondary small')}${btn('Alle abwählen','uncheckAll','','secondary small')}</div></div>${r.attendees.length?r.attendees.map((a,ai)=>`<section class="report-person" data-person-name="${esc(a.name.toLowerCase()+' '+a.number)}"><div class="report-person-header"><label class="check"><input class="present-checkbox" type="checkbox" name="present_${ai}" data-person="${ai}" ${a.present?'checked':''}><span><strong>${esc(a.name)}</strong><small> &nbsp; Stb. ${esc(a.number)}</small></span></label>${a.present?tag(a.assignments.length+' Zuordnung'+(a.assignments.length===1?'':'en')):tag('Nicht anwesend','grey')}</div>${a.present?`<div class="report-person-content">${a.assignments.map((x,xi)=>reportAssignment(a,x,ai,xi)).join('')}<div class="spacer">${btn('+ Weiteres Fahrzeug / Ausbildungsabschnitt','addAssignment',ai,'secondary small')}</div></div>`:''}</section>`).join(''):`<div class="panel">${empty('Noch keine Teilnehmer angelegt.','Nimm zuerst deine Teilnehmer in der Teilnehmerverwaltung auf.',navBtn('Teilnehmer verwalten','members','secondary'),'members')}</div>`}<section class="panel spacer"><h3>Mitwirkende Ausbilder · Zeit für den Tätigkeitsbericht</h3><p class="help">Angegeben wird die tatsächliche Mitwirkungsdauer je Ausbilder. Im Bericht zählen nur Ausbilder, die anwesenden Teilnehmern zugeordnet sind. Gemeinsame Ausbildung mehrerer Teilnehmer vervielfacht die Ausbilderstunden nicht.</p><div class="compact-grid">${state.trainers.map(t=>field(t.name+(t.number?' · Stb. '+t.number:''),'trainerMinutes_'+t.id,r.instructorMinutes?.[t.id]??reportDuration(),'number','min="1" max="1440"')).join('')}</div><div class="form-section"><h3>Eingesetzte Fahrzeuge & Kilometer (optional)</h3><p class="help">Nur tatsächlich verwendete Fahrzeuge anhaken. Ohne Kilometerangabe erscheint keine Kilometerzeile im PDF.</p><div class="compact-grid">${activeVehicles().map(v=>{const used=r.vehicleUse.find(x=>x.vehicleId===v.id);return `<div class="editor-box">${check(v.name,'used_'+v.id,!!used)}${field('Kilometer (optional)','km_'+v.id,used?.km??'','number','min="0" max="10000" step="0.1"')}</div>`;}).join('')}</div></div><div class="form-section">${area('Bemerkungen zum Tätigkeitsbericht','note',r.note)}</div></section><div class="report-actions"><span>${r.attendees.filter(a=>a.present).length} anwesende Teilnehmer · ${r.attendees.filter(a=>a.present).reduce((n,a)=>n+a.assignments.filter(x=>x.credit).length,0)} Einträge zur Anrechnung</span><div class="flex">${btn('Entwurf speichern','saveReport','','secondary')}${btn('Übung abschließen & anrechnen','finishReport','','amber')}</div></div><p class="help spacer">Beim Abschluss werden Einschulungen einmalig angerechnet. Bereits abgeschlossene Fahrzeugausbildungen bleiben erhalten. Der PDF-Bericht kann danach erstellt und an die eingestellten Empfänger versendet werden.</p></form>`;$('#reportSearch').oninput=()=>{const q=$('#reportSearch').value.toLowerCase();$$('[data-person-name]').forEach(el=>el.hidden=!el.dataset.personName.includes(q));};}
function reportAssignment(a,x,ai,xi){const p=`a_${ai}_${xi}_`,es=state.enrollments.filter(e=>e.memberId===a.memberId&&e.vehicleId===x.vehicleId),peers=reportDraft.attendees.filter(m=>m.present&&m.memberId!==a.memberId);return `<div class="assignment"><div class="panel-head"><h3>Ausbildungsabschnitt ${xi+1}</h3>${btn('Entfernen','removeAssignment',ai+':'+xi,'danger small')}</div><div class="compact-grid">${select('Fahrzeug',p+'vehicleId',[['','Allgemeine Ausbildung'],...activeVehicles().map(v=>[v.id,v.name])],x.vehicleId,`data-assignment-vehicle="${ai}:${xi}"`)}${select('Zugeordnete Fahrzeugausbildung',p+'enrollmentId',[['','Keine Anrechnung / nur Dokumentation'],...es.map(e=>[e.id,(byId('Courses',e.courseId)?.title||'Ausbildung')+(e.completedAt?' · bereits abgeschlossen':'')])],x.enrollmentId)}${field('Ausbildungsdauer in Minuten',p+'minutes',x.minutes,'number','min="1" max="1440" required')}${field('Abweichender Ausbildungsort (optional)',p+'location',x.location)}<div class="full">${area('Was wurde ausgebildet? *',p+'content',x.content,'required')}</div></div><label class="spacer">Ausbildende Personen *</label><div class="check-grid">${state.trainers.map(t=>check(t.name+(t.number?' · '+t.number:''),p+'trainer_'+t.id,x.trainerIds.includes(t.id))).join('')}</div><label class="spacer">Gemeinsam ausgebildet mit (weitere anwesende Teilnehmer)</label><div class="check-grid">${peers.map(m=>check(m.name,p+'with_'+m.memberId,x.withMemberIds.includes(m.memberId))).join('')||'<span class="help">Weitere Teilnehmer anhaken, um eine Ausbildungsgruppe festzuhalten.</span>'}</div><div class="notice spacer" style="margin-bottom:0">${check('Als praktische Fahrzeugeinschulung anrechnen',p+'credit',x.credit)}<span class="help">Eine Anrechnung pro Teilnehmer, Fahrzeugausbildung und Übung. Eine Prüfung wird dadurch nicht automatisch als bestanden markiert.</span></div></div>`;}
function collectReport(){const f=$('#reportForm');if(!f)return;const d=new FormData(f),r=reportDraft;['title','type','date','location','begins','ends','note'].forEach(k=>r[k]=d.get(k));r.attendees=r.attendees.map((a,ai)=>({...a,present:d.has('present_'+ai),assignments:a.assignments.map((x,xi)=>{const p=`a_${ai}_${xi}_`;if(!d.has(p+'vehicleId'))return x;return {...x,vehicleId:d.get(p+'vehicleId'),enrollmentId:d.get(p+'enrollmentId'),minutes:Number(d.get(p+'minutes')),location:d.get(p+'location'),content:d.get(p+'content'),trainerIds:state.trainers.filter(t=>d.has(p+'trainer_'+t.id)).map(t=>t.id),withMemberIds:r.attendees.filter(m=>d.has(p+'with_'+m.memberId)).map(m=>m.memberId),credit:d.has(p+'credit')};})}));r.vehicleUse=state.vehicles.filter(v=>d.has('used_'+v.id)).map(v=>({vehicleId:v.id,km:d.get('km_'+v.id)}));r.instructorMinutes=Object.fromEntries(state.trainers.map(t=>[t.id,Number(d.get('trainerMinutes_'+t.id))]));}
function reportView(id){const r=byId('Reports',id);openModal(r.title,`<p class="small muted">${reportType(r.type)} · ${date(r.date)} · ${esc(r.location)} · ${esc(r.begins)}–${esc(r.ends)}</p><div class="notice">Abgeschlossen und protokolliert. Einschulungen wurden je Teilnehmer und Fahrzeug einmalig angerechnet.</div><div class="table-wrap"><table><thead><tr><th>Teilnehmer</th><th>Ausbildung / Ort</th><th>Ausbilder / Gruppe</th><th>Anrechnung</th></tr></thead><tbody>${r.attendees.filter(a=>a.present).flatMap(a=>a.assignments.map(x=>`<tr><td><strong>${esc(a.name)}</strong><small>Stb. ${esc(a.number)}</small></td><td>${esc(x.vehicleName)}<small>${esc(x.content)} · ${x.minutes} Min.<br>${esc(x.location)}</small></td><td>${x.trainers.map(t=>esc(t.name)+(t.number?' · '+esc(t.number):'')).join('<br>')}<small>${x.withMemberIds.map(id=>esc(r.attendees.find(m=>m.memberId===id)?.name||'')).join(', ')}</small></td><td>${tag(x.credit&&!x.alreadyCompleted?'Einschulung':x.alreadyCompleted?'Bereits ausgebildet':'Dokumentiert',x.credit?'':'grey')}</td></tr>`)).join('')}</tbody></table></div><div class="form-actions">${btn('PDF herunterladen','reportPdf',id,'secondary')}${btn(r.emailSentAt?'PDF bereits per Mail versendet':'PDF per Mail versenden','emailReport',id,r.emailSentAt?'secondary':'teal')}</div>${r.emailSentAt?`<p class="help">Versendet am ${timeDate(r.emailSentAt)} an ${esc(r.emailRecipients)}</p>`:''}`);}
function settingsPage(){$('#content').innerHTML=heading('DEIN EIGENES SYSTEM',setupMode()?'Einrichtung der Kraftfahrerausbildung':'Einstellungen','Diese Plattform nutzt eine eigene Datenbank und eigene Zugänge. Die bestehende Grundausbildung bleibt getrennt.')+`<div class="two-cols"><div><div class="settings-steps"><section class="settings-step"><div><h3>Eigenes Installationspaket herunterladen</h3><p>Enthält die vollständige App, Code.gs, Cloudflare Worker, Anleitung und Prüfungen. Grundlage: GAB V1.13.16; Fahrzeugabläufe sind eigenständig umgesetzt.</p><p class="spacer"><a class="button secondary small" href="kraftfahrerausbildung.zip" download>↓ Installationspaket</a> <a href="INSTALLATION.md" target="_blank" rel="noopener">Anleitung lesen ↗</a> <a href="Kraftfahrerausbildung_Code.gs.txt" download>GS als Textdatei ↓</a></p></div></section><section class="settings-step"><div><h3>Neue private Google-Tabelle & Apps Script</h3><p>Eine neue Tabelle „Kraftfahrerausbildung“ anlegen, enthaltene <code>backend/Code.gs</code> einsetzen und <code>kfEinrichten</code> ausführen. Anschließend Administrator, App-Adresse und tägliche Ablauf-Erinnerungen einrichten.</p></div></section><section class="settings-step"><div><h3>Eigenen Cloudflare Worker verbinden</h3><p>Enthaltenen Worker separat bereitstellen. <code>KF_SCRIPT_URL</code>, <code>KF_WORKER_KEY</code> und erlaubte App-Adressen konfigurieren. Keinen Schlüssel und keine /exec-Adresse aus der GAB übernehmen.</p></div></section><section class="settings-step"><div><h3>App konfigurieren & anmelden</h3><p>Die neue Worker-Adresse in <code>config.js</code> als <code>window.KF_API_URL</code> eintragen und die App unter ihrer dauerhaften Adresse veröffentlichen. Danach Fahrzeuge und Ausbildungsanforderungen anlegen.</p></div></section></div></div><aside><section class="panel"><span class="eyebrow">BETRIEBSSTATUS</span><h2>${setupMode()?'Verbindung vorbereiten':'Backend verbunden'}</h2><p class="small muted">${setupMode()?'Diese veröffentlichte Oberfläche zeigt den leeren Ausgangszustand. Es sind keine Beispielteilnehmer und keine fiktiven Fahrzeugausbildungen enthalten. Speichern und Anmeldung werden mit dem eigenen Backend aktiviert.':'App und Apps-Script-Backend sind verbunden. Ausbildungsdaten werden in deiner eigenen Google-Tabelle gespeichert.'}</p><p class="help">API: ${esc(window.KF_API_URL||'Noch nicht konfiguriert')}</p>${setupMode()?'':btn('Abmelden','logout','','secondary small')}</section><section class="panel spacer"><h2>Abschlüsse bleiben bestehen.</h2><p class="small muted">Jede Teilnehmerzuordnung hält ihre Anforderungen fest. Neue Kurs- oder Quizversionen setzen weder bestandene Pflichtquiz noch anerkannte Fahrzeugausbildungen zurück.</p></section>${user?.role==='admin'?`<section class="panel spacer"><h2>Berichtsversand</h2><form id="reportSettingsForm">${area('Empfänger für fertige Tätigkeitsberichte (Komma getrennt)','recipients',state.reportRecipients||'')}<p class="help">Mit eingestellten Empfängern wird der PDF-Bericht nach dem Abschluss automatisch versendet. Der Status wird am Bericht dokumentiert.</p><button class="button small" type="submit">Empfänger speichern</button></form></section><section class="panel spacer"><div class="panel-head"><h2>Ausbilderzugänge</h2>${btn('+ Zugang','newUser','','secondary small')}</div><div class="mini-list">${state.users.filter(u=>u.role!=='participant').map(u=>`<button data-action="editUser" data-id="${u.id}"><span class="grow"><strong>${esc(u.name)}</strong><small>${esc(u.email)} · ${u.active?'Aktiv':'Deaktiviert'}</small></span><span>→</span></button>`).join('')}</div></section>`:''}</aside></div>`;}
function userForm(id=''){const u=byId('Users',id)||{role:'trainer',active:true};openModal(id?'Ausbilderzugang bearbeiten':'Ausbilderzugang anlegen',`<form id="userForm" data-id="${id}"><div class="form-grid">${field('Vor- und Nachname *','name',u.name,'text','required')}${field('E-Mail *','email',u.email,'email','required')}${field('Standesbuchnummer','number',u.number)}${select('Rolle','role',[['trainer','Ausbilder'],['admin','Administrator']],u.role)}${check('Zugang aktiv','active',u.active)}</div><p class="help spacer">Ausbilder können Teilnehmer, Fahrzeuge, Ausbildungen, Quiz und Übungen verwalten. Nur Administratoren verwalten Ausbilderzugänge und Berichtsempfänger.</p><div class="form-actions">${btn('Abbrechen','close','','secondary')}${id?btn('Einladung / Passwortlink','invite',id,'secondary'):''}<button class="button" type="submit">Zugang speichern</button></div></form>`);}
function loginPage(message=''){user=null;$('#setupBanner').hidden=true;$('#nav').innerHTML='';$('#content').innerHTML=`<section class="panel auth"><div class="brand-symbol">K↗</div><span class="eyebrow">FEUERWEHR ST. PÖLTEN-STADT</span><h1>Willkommen in deiner Kraftfahrerausbildung.</h1><p>Melde dich an, um deine Ausbildungen und Fortschritte zu öffnen.</p>${message?`<div class="notice amber">${esc(message)}</div>`:''}<form id="loginForm">${field('E-Mail','email','','email','required autocomplete="username"')}${field('Passwort','password','','password','required autocomplete="current-password" minlength="12"')}${check('30 Tage angemeldet bleiben','remember',true)}<button type="submit" class="button teal">Anmelden →</button></form><p class="help spacer">Passwort vergessen oder noch keinen Zugang? Bitte einen Ausbilder um einen neuen Einladungslink bitten.</p></section>`;$('#accountName').innerHTML='Kraftfahrerausbildung<small>Bitte anmelden</small>';$('#connection').textContent='Nicht angemeldet';}
function invitePage(invite){openModal('Deinen Zugang aktivieren',`<form id="acceptInviteForm" data-invite="${esc(invite)}"><p class="small muted">Lege ein persönliches Passwort für die Kraftfahrerausbildung fest. Vorhandene Ausbildungsnachweise bleiben erhalten.</p>${field('Neues Passwort (mindestens 12 Zeichen)','password','','password','required minlength="12" maxlength="200" autocomplete="new-password"')}${field('Passwort wiederholen','passwordAgain','','password','required minlength="12" autocomplete="new-password"')}<div class="form-actions"><button class="button teal" type="submit">Passwort festlegen</button></div></form>`);}
function downloadData(file){const data=Uint8Array.from(atob(file.base64),x=>x.charCodeAt(0)),blob=new Blob([data],{type:file.mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action],[data-nav]');if(!el||el.disabled||busy)return;if(el.dataset.nav){navigate(el.dataset.nav);return;}const action=el.dataset.action,id=el.dataset.id||'';try{switch(action){case 'close':closeModal();break;case 'refresh':await operation(async()=>{await load();toast(setupMode()?'Einrichtung noch offen.':'Ansicht aktualisiert.');});break;case 'newMember':memberForm();break;case 'editMember':memberForm(id);break;case 'member':navigate('members',id);break;case 'membersBack':navigate('members');break;case 'newVehicle':vehicleForm();break;case 'editVehicle':vehicleForm(id);break;case 'addRoom':collectVehicle();vehicleDraft.rooms.push({id:crypto.randomUUID(),name:'G'+(vehicleDraft.rooms.length+1),items:[]});renderVehicleForm();break;case 'removeRoom':collectVehicle();vehicleDraft.rooms.splice(Number(id),1);renderVehicleForm();break;case 'newCourse':courseForm();break;case 'editCourse':courseForm(id);break;case 'coursesBack':navigate('courses');break;case 'readCourse':navigate('courses',id);break;case 'addSection':collectCourse();courseDraft.sections.push({title:'',body:''});renderCourseForm();break;case 'removeSection':collectCourse();courseDraft.sections.splice(Number(id),1);renderCourseForm();break;case 'addQuestion':{collectCourse();let q;if(id==='allocation'){const v=byId('Vehicles',courseDraft.vehicleId),rooms=v?.rooms||[];if(!rooms.length||!rooms.some(r=>r.items.length)){toast('Bitte zuerst Geräteräume mit Beladung am Fahrzeug speichern.',true);return;}q={id:crypto.randomUUID(),type:'allocation',text:'Ordne die Geräte dem richtigen Geräteraum zu.',rooms:rooms.map(r=>({id:r.id,name:r.name})),items:rooms.flatMap(r=>r.items.map(i=>({id:i.id,name:i.name,correctRoomId:r.id})))};}else q={id:crypto.randomUUID(),type:id==='yesno'?'boolean':id,text:'',options:id==='boolean'?['Richtig','Falsch']:id==='yesno'?['Ja','Nein']:['',''],correct:0};courseDraft.quiz.questions.push(q);renderCourseForm();break;}case 'removeQuestion':collectCourse();courseDraft.quiz.questions.splice(Number(id),1);renderCourseForm();break;case 'assignCourse':{const available=state.courses.filter(c=>c.active&&!enrolFor(id,c.id));openModal('Fahrzeugausbildung zuordnen',available.length?`<form id="assignForm" data-id="${id}">${select('Ausbildung','courseId',available.map(c=>[c.id,c.title+' · '+byId('Vehicles',c.vehicleId)?.name]),'','required')}<p class="help spacer">Bewusste neue Zuordnung zu den aktuellen Anforderungen. Frühere Ausbildungen werden nicht verändert.</p><div class="form-actions"><button class="button" type="submit">Ausbildung zuordnen</button></div></form>`:empty('Alle aktiven Ausbildungen sind bereits zugeordnet.','Lege bei Bedarf eine neue Fahrzeugausbildung an.'));break;}case 'enrollment':enrollmentDetail(id);break;case 'lesson':lessonForm(id);break;case 'recognize':finishForm(id,true);break;case 'finishCourse':finishForm(id,false);break;case 'openLearning':closeModal();navigate('courses',id);break;case 'learning':await operation(async()=>{await api('learningComplete',{enrollmentId:id});await load();toast('Lerninhalte als durchgearbeitet bestätigt.');});break;case 'startQuiz':await operation(async()=>quizRender(await api('startQuiz',{enrollmentId:id})));break;case 'extraAttempt':await operation(async()=>{await api('extraAttempt',{enrollmentId:id});await load();closeModal();toast('Ein zusätzlicher Quizversuch freigegeben.');});break;case 'voidLesson':openModal('Einschulung korrigieren',`<form id="voidLessonForm" data-id="${id}"><div class="notice amber">Die Einschulung wird als storniert protokolliert und nicht mehr gezählt. Der ursprüngliche Eintrag bleibt erhalten.</div>${area('Begründung *','reason','','required')}<div class="form-actions"><button class="button danger" type="submit">Einschulung stornieren</button></div></form>`);break;case 'book':bookingForm(id);break;case 'chooseBooking':{const es=state.enrollments.filter(e=>e.canExam&&!e.completedAt&&e.requirements.practicalEnabled);openModal('Fahrzeug für praktische Prüfung',es.length?`<div class="mini-list">${es.map(e=>`<button data-action="book" data-id="${e.id}"><strong>${esc(byId('Vehicles',e.vehicleId)?.name)}</strong><span class="grow"></span>→</button>`).join('')}</div>`:empty('Noch keine praktische Prüfung freigeschaltet.','Zuerst Theorie und die erforderlichen Einschulungen absolvieren.'));break;}case 'confirmAppointment':case 'declineAppointment':case 'cancelAppointment':await operation(async()=>{await api('appointmentStatus',{id,status:action==='confirmAppointment'?'confirmed':action==='declineAppointment'?'declined':'cancelled'});await load();toast('Terminstatus gespeichert.');});break;case 'readNotifications':await operation(async()=>{await api('readNotifications');await load();});break;case 'invite':case 'emailInvite':await operation(async()=>{const r=await api('invite',{userId:id,sendEmail:action==='emailInvite'});openModal(r.emailSent?'Einladung versendet':'Einladungslink erstellt',`<p class="small muted">Der Link ist 7 Tage gültig und ersetzt frühere offene Links. Ausbildungsnachweise bleiben bestehen.</p><label>Persönlicher Einladungslink<input id="inviteUrl" readonly value="${esc(r.url)}"></label><div class="form-actions">${btn('Link kopieren','copyInvite','','teal')}${btn('Schließen','close','','secondary')}</div>`);});break;case 'copyInvite':try{await navigator.clipboard.writeText($('#inviteUrl').value);toast('Link kopiert.');}catch{$('#inviteUrl').select();toast('Bitte den markierten Link kopieren.');}break;case 'upload':openModal('Führerscheinnachweis hochladen',`<form id="uploadForm" data-id="${id}">${select('Nachweis','kind',[['licence','Führerschein'],['fireLicence','Feuerwehrführerschein']])}<label class="spacer">Datei (PDF, JPEG oder PNG, maximal 2 MB)<input type="file" name="file" accept="application/pdf,image/jpeg,image/png" required></label><div class="form-actions"><button class="button teal" type="submit">Privat hochladen</button></div></form>`);break;case 'download':await operation(async()=>downloadData(await api('download',{fileId:id})));break;case 'newUser':userForm();break;case 'editUser':userForm(id);break;case 'newThursday':newReport('thursday');break;case 'newExtra':openModal('Außerordentliche Kraftfahrerausbildung',`<p class="small muted">Für Ausbildungen und Prüfungen außerhalb der wöchentlichen Donnerstagsübung. Einschulungen können genauso angerechnet werden.</p><div class="inline-actions">${btn('Außerordentliche Kraftfahrübung','newExtraTraining','','teal')}${btn('Außerordentliche Kraftfahrprüfung','newExtraExam','','secondary')}</div>`);break;case 'newExtraTraining':closeModal();newReport('extra');break;case 'newExtraExam':closeModal();newReport('exam');break;case 'editReport':newReport('thursday',id);break;case 'reportsBack':if(reportDraft)openModal('Übungsentwurf verlassen?',`<p class="small muted">Noch nicht gespeicherte Eingaben gehen beim Verlassen verloren.</p><div class="form-actions">${btn('Weiter bearbeiten','close','','secondary')}${btn('Ohne Speichern verlassen','discardReport','','danger')}</div>`);else navigate('reports');break;case 'discardReport':closeModal();reportDraft=null;navigate('reports');break;case 'checkAll':case 'uncheckAll':collectReport();reportDraft.attendees.forEach(a=>{a.present=action==='checkAll';if(a.present&&!a.assignments.length)a.assignments.push(defaultAssignment(a.memberId));});renderReportEditor();break;case 'addAssignment':collectReport();reportDraft.attendees[Number(id)].assignments.push(defaultAssignment(reportDraft.attendees[Number(id)].memberId));renderReportEditor();break;case 'removeAssignment':{collectReport();const [ai,xi]=id.split(':').map(Number);reportDraft.attendees[ai].assignments.splice(xi,1);renderReportEditor();break;}case 'saveReport':case 'finishReport':{if(!$('#reportForm').reportValidity())return;collectReport();if(action==='finishReport'){openModal('Übung abschließen & Einschulungen anrechnen?',`<p>Du bestätigst ${reportDraft.attendees.filter(a=>a.present).length} anwesende Teilnehmer. Die markierten Fahrzeugeinschulungen werden einmal je Fahrzeugausbildung angerechnet.</p><p class="help">Der Bericht wird danach unveränderlich. ${state.reportAutoEmail?'Das PDF wird anschließend an die eingestellten Berichtsempfänger versendet.':'Das PDF kann anschließend heruntergeladen oder per Mail versendet werden, sobald Empfänger eingestellt sind.'}</p><div class="form-actions">${btn('Zurück','close','','secondary')}${btn('Verbindlich abschließen','confirmFinishReport','','teal')}</div>`);}else await operation(async()=>{const r=await api('saveReport',reportDraft);reportDraft.id=r.id;toast('Übungsentwurf gespeichert.');});break;}case 'confirmFinishReport':await operation(async()=>{const saved=await api('saveReport',reportDraft);reportDraft.id=saved.id;const finished=await api('finishReport',{id:saved.id});reportDraft=null;closeModal();await load();toast(finished.emailError?'Übung abgeschlossen und angerechnet. PDF-Versand noch offen: '+finished.emailError:'Übung abgeschlossen. Einschulungen angerechnet.',!!finished.emailError);});break;case 'resumeReport':await operation(async()=>{const r=await api('finishReport',{id});await load();toast(r.emailError?'Abgeschlossen. PDF-Mail noch offen: '+r.emailError:'Abschluss erfolgreich fortgesetzt.',!!r.emailError);});break;case 'viewReport':reportView(id);break;case 'reportPdf':await operation(async()=>downloadData(await api('reportPdf',{id})));break;case 'emailReport':await operation(async()=>{const r=await api('emailReport',{id});closeModal();await load();toast(r.alreadySent?'Dieser Bericht wurde bereits versendet.':'PDF-Bericht per E-Mail versendet.');});break;case 'logout':await operation(async()=>{try{await api('logout');}finally{token='';localStorage.removeItem('kf_session');sessionStorage.removeItem('kf_session');state={...EMPTY};user=null;closeModal();loginPage();}});break;}}catch(e){toast(e.message,true);}});
document.addEventListener('change',e=>{if(!reportDraft)return;if(e.target.matches('.present-checkbox')){const i=Number(e.target.dataset.person),present=e.target.checked;collectReport();const a=reportDraft.attendees[i];a.present=present;if(present&&!a.assignments.length)a.assignments.push(defaultAssignment(a.memberId));reportDraft.attendees.forEach(m=>m.assignments.forEach(x=>x.withMemberIds=x.withMemberIds.filter(id=>reportDraft.attendees.some(a=>a.memberId===id&&a.present))));renderReportEditor();}else if(e.target.matches('[data-assignment-vehicle]')){const [ai,xi]=e.target.dataset.assignmentVehicle.split(':').map(Number);collectReport();const a=reportDraft.attendees[ai],x=a.assignments[xi],en=state.enrollments.find(en=>en.memberId===a.memberId&&en.vehicleId===x.vehicleId&&!en.completedAt)||state.enrollments.find(en=>en.memberId===a.memberId&&en.vehicleId===x.vehicleId);x.enrollmentId=en?.id||'';x.credit=!!en&&!en.completedAt&&reportDraft.type!=='exam';renderReportEditor();}});
document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('form'))return;e.preventDefault();if(busy)return;operation(async()=>{const d=new FormData(f),id=f.dataset.id;switch(f.id){case 'loginForm':{const r=await api('login',{email:d.get('email'),password:d.get('password'),remember:d.has('remember')});token=r.token;localStorage.removeItem('kf_session');sessionStorage.removeItem('kf_session');(d.has('remember')?localStorage:sessionStorage).setItem('kf_session',token);user=r.user;await load();break;}case 'acceptInviteForm':if(d.get('password')!==d.get('passwordAgain'))throw Error('Passwörter stimmen nicht überein.');await api('acceptInvite',{invite:f.dataset.invite,password:d.get('password')});history.replaceState(null,'',location.pathname);closeModal();loginPage('Passwort gespeichert. Du kannst dich jetzt anmelden.');break;case 'memberForm':{const data={id,firstName:d.get('firstName'),lastName:d.get('lastName'),number:d.get('number'),email:d.get('email'),phone:d.get('phone'),startDate:d.get('startDate'),active:d.has('active'),fireLicenceExpires:d.get('fireLicenceExpires'),licences:CLASSES.filter(c=>d.has('class_'+c)).map(c=>({class:c,expires:d.get('expiry_'+c)}))};const saved=await api('saveMember',data);selectedId=saved.id;closeModal();await load();toast('Teilnehmer gespeichert.');break;}case 'vehicleForm':collectVehicle();await api('saveVehicle',vehicleDraft);closeModal();route='vehicles';await load();toast('Fahrzeug gespeichert.');break;case 'courseForm':collectCourse();await api('saveCourse',courseDraft);closeModal();route='courses';selectedId='';await load();toast('Ausbildung gespeichert. Bestehende Abschlüsse bleiben angerechnet.');break;case 'assignForm':await api('assign',{memberId:id,courseId:d.get('courseId')});closeModal();await load();toast('Ausbildung zugeordnet.');break;case 'lessonForm':await api('saveLesson',{enrollmentId:id,date:d.get('date'),minutes:d.get('minutes'),content:d.get('content'),clientKey:f.dataset.key});closeModal();await load();toast('Praktische Einschulung angerechnet.');break;case 'finishForm':await api('complete',{enrollmentId:id,date:d.get('date'),recognition:f.dataset.recognition==='true',reason:d.get('reason'),examPassed:d.has('examPassed')});closeModal();await load();toast('Fahrzeugausbildung bestätigt und dauerhaft angerechnet.');break;case 'quizForm':{const answers={};quizAttempt.questions.forEach(q=>{if(q.type==='allocation')answers[q.id]=Object.fromEntries(q.items.map(it=>[it.id,d.get('allocation_'+q.id+'_'+it.id)]));else answers[q.id]=Number(d.get('answer_'+q.id));});const result=await api('submitQuiz',{attemptId:quizAttempt.id,answers});await load();openModal('Dein Quizergebnis',`<div class="result"><span class="eyebrow">${result.passed?'GRATULATION!':'WEITERLERNEN LOHNT SICH.'}</span><h2>${result.passed?'Quiz erfolgreich bestanden.':'Diesmal noch nicht bestanden.'}</h2><div class="result-score">${result.percent} %</div><p class="small muted">${result.points} von ${result.maxPoints} Punkten</p><p>${result.passed?'Dein Erfolg wurde gespeichert und bleibt bei späteren Inhaltsänderungen angerechnet.':'Schau dir die Lerninhalte nochmals an. Bei ausgeschöpften Versuchen kann dir dein Ausbilder einen Zusatzversuch freigeben.'}</p>${btn('Zurück zur Ausbildung','close','','teal')}</div>`);break;}case 'bookingForm':await api('appointment',{enrollmentId:id,trainerId:d.get('trainerId'),begins:new Date(d.get('begins')).toISOString(),note:d.get('note')});closeModal();route='appointments';await load();toast('Prüfungstermin gespeichert.');break;case 'uploadForm':{const file=d.get('file');if(file.size>2*1024*1024)throw Error('Maximal 2 MB pro Nachweis.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('upload',{memberId:id,kind:d.get('kind'),name:file.name,mime:file.type,base64});closeModal();await load();toast('Nachweis privat gespeichert.');break;}case 'userForm':await api('saveUser',{id,name:d.get('name'),email:d.get('email'),number:d.get('number'),role:d.get('role'),active:d.has('active')});closeModal();await load();toast('Ausbilderzugang gespeichert. Einladung kann jetzt erstellt werden.');break;case 'reportSettingsForm':await api('reportSettings',{recipients:d.get('recipients')});await load();toast('Berichtsempfänger gespeichert.');break;case 'voidLessonForm':await api('voidLesson',{id,reason:d.get('reason')});closeModal();await load();toast('Einschulung als storniert protokolliert.');break;}});});
$('#closeModal').onclick=()=>{if(!busy)closeModal();};$('#modal').addEventListener('cancel',e=>{if(busy)e.preventDefault();});$('#menuButton').onclick=()=>$('#sidebar').classList.toggle('open');$('#backdrop').onclick=()=>$('#sidebar').classList.remove('open');$('#accountButton').onclick=()=>{if(user)openModal('Dein Konto',`<h3>${esc(user.name)}</h3><p class="small muted">${esc(user.email)}</p><div class="form-actions">${btn('Abmelden','logout','','secondary')}${btn('Schließen','close','','teal')}</div>`);else navigate('settings');};
window.addEventListener('beforeunload',e=>{if(reportDraft){e.preventDefault();e.returnValue='';}});
(async()=>{const hash=location.hash.slice(1),invite=hash.startsWith('invite=')?hash.slice(7):'';if(!invite&&hash)route=['dashboard','members','vehicles','courses','reports','appointments','progress','notifications','settings','profile'].includes(hash)?hash:'dashboard';try{if(setupMode())render();else if(token)await load();else loginPage();if(invite){history.replaceState(null,'',location.pathname);invitePage(invite);}if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});}catch(e){toast(e.message,true);}})();
